 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const candidates = [];
+  for (const [index, part] of header.split(",").entries()) {
+    const [rawTag, ...params] = part.trim().split(";");
+    if (!rawTag) continue;
+    const lang = rawTag.trim().split(/[-_]/)[0].toLowerCase();
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const [k, v = ""] = p.split("=").map((s) => s.trim());
+      if (k.toLowerCase() === "q") {
+        const n = Number(v);
+        if (v === "" || Number.isNaN(n) || n < 0 || n > 1) valid = false;
+        else q = n;
+      }
+    }
+    if (valid && q > 0) candidates.push({ lang, q, index });
+  }
+  if (!candidates.length) return fallback;
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0].lang;
+}
